import {systems,defaults,parseExpression,step,distance} from './science.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let cfg=defaults('lorenz'),result=null,comparison=null,playing=true,progress=.72,speed=1,autoRotate=!matchMedia('(prefers-reduced-motion: reduce)').matches,angle=.4,tilt=.23,zoom=1,view='3d',page='lab',activeTab='simulation',version=0;
const worker=new Worker('./worker.js',{type:'module'}),pending=new Map();let requestId=0;
worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result);};
worker.onerror=()=>{pending.forEach(p=>p.reject(Error('Computation worker could not start. Reload this page.')));pending.clear();toast('Computation worker unavailable.');};
function compute(task,...args){return new Promise((resolve,reject)=>{const id=++requestId;pending.set(id,{resolve,reject});worker.postMessage({id,task,args});});}
let dialogEpoch=0;
async function toolCompute(task,...args){const epoch=dialogEpoch;const result=await compute(task,...args);if(epoch!==dialogEpoch||!$('#toolDialog').open)throw Error('Analysis canceled.');return result;}
let toastTimer;function toast(message){if(message==='Analysis canceled.')return;$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function safeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Browser storage is unavailable. Export your experiment to keep it.');return false;}}
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
const fmt=(n,d=3)=>Number.isFinite(n)?n.toFixed(d):'—';
function renderConfig(){const s=systems[cfg.system];$('#system').value=cfg.system;$('#systemKind').textContent=s.kind.toUpperCase();$('#systemDim').textContent=s.initial.length+'D SYSTEM';$('#equations').innerHTML=s.equations.join('<br>');$('#parameters').innerHTML=s.params.map(([key,symbol,,min,max])=>`<div class="parameter"><div class="parameter-head"><label for="param-${key}"><span class="parameter-symbol">${symbol}</span> <span>${({sigma:'Sigma',rho:'Rho',beta:'Beta',mu:'Mu',delta:'Delta',gamma:'Gamma',omega:'Omega',alpha:'Alpha',g:'Gravity',l1:'Length 1',l2:'Length 2',k:'Coupling',r:'Growth rate'})[key]||key}</span></label><input id="param-${key}" type="number" value="${cfg.params[key]}" min="${min}" max="${max}" step="any" data-param="${key}"></div><input type="range" min="${min}" max="${max}" step="${(max-min)/400}" value="${cfg.params[key]}" aria-label="${key} parameter" data-range="${key}"><div class="range-ends"><span>${min}</span><span>${max}</span></div></div>`).join('');const names=cfg.system==='pendulum'?['θ₁','θ₂','ω₁','ω₂']:['x₀','y₀','z₀','w₀'];$('#initials').style.gridTemplateColumns=`repeat(${Math.min(4,s.initial.length)},1fr)`;$('#initials').innerHTML=cfg.initial.map((v,i)=>`<label for="initial-${i}">${names[i]}<input id="initial-${i}" data-initial="${i}" type="number" step="any" value="${v}"></label>`).join('');$('#solver').value=cfg.solver;$('#step').value=cfg.dt;$('#duration').value=cfg.duration;$('#solver').disabled=s.kind==='discrete';$('#step').disabled=s.kind==='discrete';$('#plotSystem').textContent=s.name.toUpperCase();$('#dimension').innerHTML=`${s.initial.length} <small>variables</small>`;$('#plotStatus').textContent='LIVE SIMULATION';$('#parameters').oninput=e=>{if(e.target.dataset.range){const key=e.target.dataset.range;$('#param-'+key).value=Number(Number(e.target.value).toFixed(4));}if(e.target.dataset.param){const range=$(`[data-range="${e.target.dataset.param}"]`);range.value=e.target.value;}};$('#parameters').onchange=()=>runSimulation();}
function readConfig(){const next={...cfg,params:{...cfg.params},initial:[...cfg.initial],dt:Number($('#step').value),duration:Number($('#duration').value),solver:$('#solver').value};$$('[data-param]').forEach(el=>next.params[el.dataset.param]=Number(el.value));$$('[data-initial]').forEach(el=>next.initial[Number(el.dataset.initial)]=Number(el.value));return next;}
async function runSimulation(){const current=++version;$('#run').disabled=true;$('#run span').textContent='Computing…';try{const next=readConfig();const r=await compute('simulate',next);if(current!==version)return;cfg=next;result=r;comparison=null;progress=.72;playing=true;$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause simulation');$('.legend-b').hidden=true;$('#timeEnd').textContent=fmt(r.times.at(-1),2)+(systems[cfg.system].kind==='discrete'?' n':' s');$('#simulationTime').innerHTML=fmt(r.times.at(-1),2)+' <small>'+(cfg.system==='logistic'?'iterations':'s')+'</small>';$('#integrationSteps').textContent=r.steps.toLocaleString();$('#pointCount').textContent=r.points.length.toLocaleString();$('#solverStatus').textContent=cfg.system==='logistic'?'MAP':cfg.solver.toUpperCase();$('#stepLabel').textContent=cfg.system==='logistic'?'1':fmt(cfg.dt);$('#lyapunov').textContent='…';$('#lyapInterpretation').textContent='Estimating…';updateTimeChart();prepareBounds();compute('lyapunov',cfg).then(l=>{if(current!==version)return;$('#lyapunov').textContent=l.value===null?'Unavailable':(l.value>=0?'+':'')+fmt(l.value,4);$('#lyapInterpretation').textContent=l.value>.05?'Positive estimate':l.value<-.05?'Contracting estimate':'Near-zero estimate';$('#behavior').innerHTML=(l.value>.05?'Sensitive dynamics':l.value<-.05?'Contracting dynamics':'Oscillatory dynamics')+'<small>Finite-time numerical observation</small>';lineChart($('#lyapChart'),[l.history],['#b297ff'],{minimal:true});}).catch(e=>toast(e.message));safeStore('tosin-current',cfg);}catch(e){toast(e.message);}finally{if(current===version){$('#run').disabled=false;$('#run span').textContent='Run simulation';}}}
function sizeCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(rect.width<1||rect.height<1)return null;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w:rect.width,h:rect.height};}
let bounds={center:[0,0,25],scale:1};
function mapPoint(p,i=0){if(cfg.system==='logistic')return[p[0],result?.points[Math.max(0,i-1)]?.[0]||0,0];return[p[0],p[1]||0,p[2]||0];}
function prepareBounds(){if(!result)return;const pts=result.points.map(mapPoint);const min=[0,1,2].map(j=>Math.min(...pts.map(p=>p[j]))),max=[0,1,2].map(j=>Math.max(...pts.map(p=>p[j])));bounds={center:min.map((v,i)=>(v+max[i])/2),scale:Math.max(...max.map((v,i)=>v-min[i]),1)};}
function project(p,w,h,raw=false){let [x,y,z]=raw?p:p.map((v,i)=>(v-bounds.center[i])/bounds.scale);if(view==='2d'){return[w*.5+x*w*.72*zoom,h*.49-y*h*.75*zoom];}const ca=Math.cos(angle),sa=Math.sin(angle),ct=Math.cos(tilt),st=Math.sin(tilt);const xx=x*ca+y*sa,yy=-x*sa+y*ca;const zz=z*ct-yy*st,depth=yy*ct+z*st;const perspective=1/(1+depth*.35);const scale=Math.min(w*.85,h*.8)*zoom;return[w*.48+xx*scale*perspective,h*.51-zz*scale*perspective];}
function drawPhase(){const sized=sizeCanvas($('#phase'));if(!sized)return;const{ctx,w,h}=sized;ctx.clearRect(0,0,w,h);ctx.lineWidth=.6;
 // A quiet spatial lattice anchors the attractor without competing with it.
 for(let j=-5;j<=5;j++){for(const dir of [0,1]){const p=dir?[j/10,-.55,-.54]:[-.55,j/10,-.54],q=dir?[j/10,.55,-.54]:[.55,j/10,-.54];const a=project(p,w,h,true),b=project(q,w,h,true);ctx.strokeStyle=j===0?'#21404b':'#142a35';ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();}}
 if(!result)return;const count=Math.max(2,Math.floor(result.points.length*progress));const draw=(points,color,alpha=1)=>{ctx.globalAlpha=alpha;ctx.lineWidth=1;ctx.strokeStyle=color;ctx.shadowColor=color;ctx.shadowBlur=7;ctx.beginPath();const skip=Math.max(1,Math.floor(count/6500));for(let i=0;i<count;i+=skip){const p=project(mapPoint(points[i],i),w,h);if(i===0)ctx.moveTo(...p);else ctx.lineTo(...p);}if(cfg.system==='logistic'){ctx.shadowBlur=0;ctx.fillStyle=color;for(let i=0;i<count;i+=skip){const p=project(mapPoint(points[i],i),w,h);ctx.beginPath();ctx.arc(...p,1.1,0,Math.PI*2);ctx.fill();}}else ctx.stroke();ctx.shadowBlur=0;ctx.globalAlpha=1;const head=project(mapPoint(points[count-1],count-1),w,h);const g=ctx.createRadialGradient(...head,0,...head,10);g.addColorStop(0,color);g.addColorStop(.2,color+'aa');g.addColorStop(1,color+'00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(...head,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ddfff8';ctx.beginPath();ctx.arc(...head,2,0,Math.PI*2);ctx.fill();};draw(result.points,'#39e8c3',comparison?.7:.86);if(comparison)draw(comparison.points,'#b297ff',.8);
 const t=result.times[count-1];$('#currentTime').textContent=fmt(t,2);$('#timeline').value=Math.floor(progress*1000);}
let lastTime=0;function animate(t){const elapsed=Math.min(t-lastTime,60);lastTime=t;if(page==='lab'&&activeTab==='simulation'){if(playing&&result){progress+=elapsed*.000012*speed;if(progress>1)progress=.08;}if(autoRotate)angle+=elapsed*.000018;drawPhase();}requestAnimationFrame(animate);}requestAnimationFrame(animate);
function lineChart(canvas,series,colors,{minimal=false,log=false,xValues=null,band=false}={}){const sized=sizeCanvas(canvas);if(!sized)return;const{ctx,w,h}=sized;ctx.clearRect(0,0,w,h);let vals=series.flat().filter(Number.isFinite);if(!vals.length)return;const transform=v=>log?Math.log10(Math.max(v,1e-12)):v;vals=vals.map(transform);let min=Infinity,max=-Infinity;for(const value of vals){min=Math.min(min,value);max=Math.max(max,value);}if(max-min<1e-8){min-=.5;max+=.5;}const pad=minimal?4:32,right=minimal?4:12,top=minimal?4:15,bottom=minimal?4:25;const px=i=>pad+i/Math.max(1,series[0].length-1)*(w-pad-right),py=v=>h-bottom-(transform(v)-min)/(max-min)*(h-top-bottom);if(!minimal){ctx.font='8px "IBM Plex Mono",monospace';ctx.textAlign='right';for(let i=0;i<5;i++){const y=top+(h-top-bottom)*i/4;ctx.strokeStyle='#1c2b35';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle='#587383';const v=max-(max-min)*i/4;ctx.fillText(log?'10^'+v.toFixed(0):v.toFixed(Math.abs(v)<3?1:0),pad-8,y+3);}ctx.textAlign='center';for(let i=0;i<6;i++){const idx=Math.round(i*(series[0].length-1)/5);ctx.fillStyle='#587383';ctx.fillText(xValues?Number(xValues[idx]).toFixed(0):String(idx),px(idx),h-6);}}
 if(band&&series.length>=2){ctx.fillStyle='#39e8c318';ctx.beginPath();series[0].forEach((v,i)=>{i?ctx.lineTo(px(i),py(v)):ctx.moveTo(px(i),py(v));});for(let i=series[1].length-1;i>=0;i--)ctx.lineTo(px(i),py(series[1][i]));ctx.closePath();ctx.fill();}series.forEach((values,index)=>{ctx.strokeStyle=colors[index%colors.length];ctx.lineWidth=minimal?1:1.1;ctx.globalAlpha=.8;ctx.beginPath();const stride=Math.max(1,Math.floor(values.length/w/2));for(let i=0;i<values.length;i+=stride){const x=px(i),y=py(values[i]);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.stroke();ctx.globalAlpha=1;});}
function updateTimeChart(){if(result)lineChart($('#timeChart'),[0,1,2].slice(0,result.points[0].length).map(j=>result.points.map(p=>p[j])),['#39e8c3','#b297ff','#5e9ef7'],{xValues:result.times});}
let dragging=false,dragX=0,dragY=0,moved=false;$('#phase').onpointerdown=e=>{dragging=true;moved=false;dragX=e.clientX;dragY=e.clientY;$('#phase').setPointerCapture(e.pointerId);};$('#phase').onpointermove=e=>{if(dragging){const dx=e.clientX-dragX,dy=e.clientY-dragY;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;if(e.shiftKey){bounds.center[0]-=dx*bounds.scale/500;bounds.center[2]+=dy*bounds.scale/500;}else{angle+=dx*.008;tilt=Math.max(-1.5,Math.min(1.5,tilt+dy*.008));}dragX=e.clientX;dragY=e.clientY;}else if(!playing&&result){const rect=$('#phase').getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;let nearest=null,best=225;for(let i=0;i<result.points.length*progress;i+=4){const p=project(mapPoint(result.points[i],i),rect.width,rect.height);const d=(p[0]-x)**2+(p[1]-y)**2;if(d<best){best=d;nearest=i;}}$('#inspectValue').hidden=nearest===null;if(nearest!==null)$('#inspectValue').textContent=`t ${fmt(result.times[nearest],3)} · [${result.points[nearest].map(v=>fmt(v,3)).join(', ')}]`;}};$('#phase').onpointerup=()=>dragging=false;$('#phase').onpointerleave=()=>$('#inspectValue').hidden=true;$('#phase').onwheel=e=>{e.preventDefault();zoom=Math.max(.3,Math.min(4,zoom*Math.exp(-e.deltaY*.001)));};$('#phase').addEventListener('wheel',()=>{},{passive:false});
$('#run').onclick=runSimulation;$('#system').onchange=()=>{cfg=defaults($('#system').value);renderConfig();runSimulation();};$('#resetParams').onclick=()=>{cfg=defaults(cfg.system);renderConfig();runSimulation();};$('#solver').onchange=runSimulation;$('#play').onclick=()=>{playing=!playing;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause simulation':'Resume simulation');$('#plotStatus').textContent=playing?'LIVE SIMULATION':'PAUSED · INSPECT TRAJECTORY';};$('#restart').onclick=()=>{progress=.01;playing=true;$('#play').textContent='Ⅱ';};$('#timeline').oninput=()=>{playing=false;progress=Math.max(.001,Number($('#timeline').value)/1000);$('#play').textContent='▶';$('#plotStatus').textContent='PAUSED · INSPECT TRAJECTORY';};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:speed===4?.5:1;$('#speed').textContent=speed+'×';};$('#rotate').onclick=()=>{autoRotate=!autoRotate;$('#rotate').classList.toggle('active',autoRotate);};$('#zoomIn').onclick=()=>zoom=Math.min(4,zoom*1.2);$('#zoomOut').onclick=()=>zoom=Math.max(.3,zoom/1.2);$('#resetView').onclick=()=>{angle=.4;tilt=.23;zoom=1;prepareBounds();};$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(el=>el.classList.toggle('active',el===b));});$('#expandPlot').onclick=()=>{$('.phase-panel').classList.toggle('fullscreen');};
