const pageMeta={lab:['Dynamics Lab','Small changes. Extraordinary consequences. Explore the mathematics of motion.'],library:['System Library','Eight mathematical worlds. Choose a system and follow its dynamics.'],experiments:['My Experiments','Keep your hypotheses, parameters, and discoveries reproducible.']};
function setPage(next){page=next;$$('[data-tab]').forEach(b=>{const selected=b.dataset.tab===activeTab;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',String(selected));});$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===next));$('#pageTitle').innerHTML=pageMeta[next][0]+'<span>.</span>';$('#pageDescription').textContent=pageMeta[next][1];$('#crumb').textContent=pageMeta[next][0];$('.workspace-tabs').hidden=next!=='lab';$('#labPage').hidden=next!=='lab'||activeTab!=='simulation';$('#analysisPage').hidden=next!=='lab'||activeTab!=='analysis';$('#notesPage').hidden=next!=='lab'||activeTab!=='notes';$('#libraryPage').hidden=next!=='library';$('#experimentsPage').hidden=next!=='experiments';$('.welcome-strip').hidden=next==='experiments';if(next==='library')renderLibrary();if(next==='experiments')renderExperiments();if(next==='lab')updateTimeChart();}
$$('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));$('#exploreSystems').onclick=()=>setPage('library');$$('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;$$('[data-tab]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-selected',String(el===b));});setPage('lab');if(activeTab==='analysis')renderAnalysis();});
function renderLibrary(){$('#libraryPage').innerHTML='<div class="library-grid">'+Object.entries(systems).map(([id,s])=>`<button class="system-card" data-system-card="${id}"><canvas class="card-art" data-art="${id}"></canvas><h3>${s.name}</h3><p>${s.description}</p><small>${s.initial.length}D · ${s.kind} <span style="float:right">Open in lab ↗</span></small></button>`).join('')+'</div>';$$('[data-system-card]').forEach(b=>b.onclick=()=>{cfg=defaults(b.dataset.systemCard);renderConfig();activeTab='simulation';$$('[data-tab]').forEach(el=>el.classList.toggle('selected',el.dataset.tab==='simulation'));setPage('lab');runSimulation();});$$('[data-art]').forEach(async canvas=>{try{const id=canvas.dataset.art,r=await compute('simulate',{...defaults(id),duration:id==='rossler'?100:30});if(!canvas.isConnected)return;const sized=sizeCanvas(canvas);if(!sized)return;const{ctx,w,h}=sized;const pts=r.points.slice(200),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[2]??p[1]??p[0]);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);ctx.strokeStyle=id==='lorenz'||id==='duffing'||id==='coupled'?'#39e8c3':'#b297ff';ctx.globalAlpha=.75;ctx.lineWidth=.7;ctx.beginPath();pts.forEach((p,i)=>{const x=10+(xs[i]-xmin)/(xmax-xmin||1)*(w-20),y=5+(ys[i]-ymin)/(ymax-ymin||1)*(h-10);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}catch{}});}
const toolNames=['Chaos Challenge','Lyapunov Analyzer','Bifurcation Explorer','Predictability Horizon','Algorithm Arena','Uncertainty Lab','Sensitivity Analysis','Fractal Analysis','Poincaré Section','Recurrence Analysis','Inverse Chaos Solver','Chaos Control','Parameter Estimation','System Identification','Chaos vs Randomness','Coupled Chaos Network','Custom Equation Lab'];
function renderAnalysis(){$('#analysisPage').innerHTML='<div class="analysis-grid">'+toolNames.map((name,i)=>`<section class="panel analysis-card"><span class="tiny-icon ${i%2?'purple':'teal'}">${['λ','⌁','⋔','δ','∿','◈'][i%6]}</span><h3>${name}</h3><p>${toolDescriptions[name]||'Explore a numerical experiment with explicit assumptions and transparent limitations.'}</p><button class="outline-btn" data-analysis-tool="${name}">Open workbench ↗</button></section>`).join('')+'</div>';$$('[data-analysis-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.analysisTool));}
function saveExperiment(name){const experiments=readStore('tosin-experiments',[]);const record={id:Date.now(),name,cfg:readConfig(),notes:$('#notes').value,date:new Date().toISOString()};experiments.unshift(record);if(safeStore('tosin-experiments',experiments))toast('Experiment saved in this browser.');$('.experiment-name').innerHTML='<span class="status-dot"></span>';$('.experiment-name').append(document.createTextNode(name+' · browser local'));}
$('#newExperiment').onclick=()=>{openDialog('Save experiment',`<p>Save the complete configuration and notes. Export JSON to move it between devices.</p><div class="tool-controls"><label>Experiment name<input class="tool-input" id="experimentName" maxlength="100" value="${systems[cfg.system].name} experiment"></label><button id="confirmSave">Save experiment</button><button id="exportExperiment">Export JSON</button></div>`);$('#confirmSave').onclick=()=>{const name=$('#experimentName').value.trim();if(!name)return toast('Enter an experiment name.');saveExperiment(name);$('#toolDialog').close();};$('#exportExperiment').onclick=()=>download('tosin-experiment.json',JSON.stringify({schemaVersion:1,configuration:readConfig(),notes:$('#notes').value,created:new Date().toISOString()},null,2));};
function renderExperiments(){const experiments=readStore('tosin-experiments',[]);$('#experimentsPage').innerHTML=`<div class="tool-controls"><label>Import experiment JSON<input id="importExperiment" type="file" accept=".json"></label></div><section class="panel" id="experimentList"></section>`;const list=$('#experimentList');if(!experiments.length){list.innerHTML='<div class="empty-state"><h2>Your next discovery starts here.</h2><p>Run a simulation and use “New experiment” to preserve the configuration.<br>Your experiments stay in this browser. Export JSON for a portable copy.</p><button class="outline-btn" id="backToLab">Open Dynamics Lab ↗</button></div>';$('#backToLab').onclick=()=>setPage('lab');}else for(const exp of experiments){const row=document.createElement('div');row.className='experiment-row';const info=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('p');title.textContent=exp.name;sub.textContent=`${systems[exp.cfg.system]?.name||'Unknown model'} · ${new Date(exp.date).toLocaleDateString()} · ${exp.cfg.solver.toUpperCase()}`;info.append(title,sub);row.append(info);for(const label of ['Open','Export','Delete']){const b=document.createElement('button');b.textContent=label;if(label==='Delete')b.className='delete';b.onclick=()=>{if(label==='Open'){cfg=structuredClone(exp.cfg);$('#notes').value=exp.notes||'';renderConfig();setPage('lab');runSimulation();}else if(label==='Export')download('tosin-experiment.json',JSON.stringify({schemaVersion:1,configuration:exp.cfg,notes:exp.notes},null,2));else{safeStore('tosin-experiments',experiments.filter(e=>e.id!==exp.id));renderExperiments();}};row.append(b);}list.append(row);}$('#importExperiment').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.schemaVersion!==1||!systems[data.configuration?.system])throw Error('Unsupported experiment format.');await compute('simulate',data.configuration);cfg=data.configuration;$('#notes').value=String(data.notes||'');renderConfig();setPage('lab');runSimulation();toast('Experiment imported and validated.');}catch(e){toast('Could not import: '+e.message);}};}
