$('#toolDialog').addEventListener('close',()=>dialogEpoch++);$('#closeDialog').onclick=()=>$('#toolDialog').close();$('#toolDialog').addEventListener('click',e=>{if(e.target===$('#toolDialog')){const r=$('#toolDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#toolDialog').close();}});
const resultCards=cards=>'<div class="results-grid">'+cards.map(([label,value])=>`<div class="result-card"><small>${label}</small><strong>${value}</strong></div>`).join('')+'</div>';
const toolChart='<canvas id="toolChart" class="tool-chart"></canvas>';
function busy(button,fn){button.disabled=true;const text=button.textContent;button.textContent='Computing…';Promise.resolve().then(fn).catch(e=>toast(e.message)).finally(()=>{button.disabled=false;button.textContent=text;});}
async function openTool(name){if(!result&&name!=='Bifurcation Explorer')return toast('Run a valid simulation first.');if(name==='More tools'){openDialog('Analysis toolkit','<p>Select a mathematical instrument for the current experiment.</p><div class="tool-list">'+toolNames.map(n=>`<button data-pick-tool="${n}">${n}<span>↗</span></button>`).join('')+'</div>');$$('[data-pick-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.pickTool));return;}
 if(name==='Chaos Challenge'||name==='Predictability Horizon'){
 openDialog(name,`<p>Two trajectories. Identical parameters and solver. A small perturbation in the first initial coordinate. The horizon is the first <em>sampled</em> time that their Euclidean separation exceeds your tolerance.</p><div class="tool-equation">δ(t) = ‖xᴬ(t) − xᴮ(t)‖₂ &nbsp; · &nbsp; T = inf{t : δ(t) ≥ ε}</div><div class="tool-controls"><label>Initial perturbation δ₀<input id="delta" class="tool-input" type="number" value="0.0001" min="0.00000001" step="0.0001"></label><label>Error tolerance ε<input id="tolerance" class="tool-input" type="number" value="1" min="0.000001" step="0.1"></label><button id="computeTool">Compare trajectories</button><button id="inspectHorizon" hidden>Inspect horizon in lab ↗</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">A paired-trajectory experiment is not a confidence bound. Results depend on units, initial conditions, integration error, and sampling. A missing crossing means only that the tolerance was not reached in this interval.</p>`);
 const run=()=>busy($('#computeTool'),async()=>{const delta=Number($('#delta').value),tolerance=Number($('#tolerance').value);if(!(delta>0&&tolerance>0&&Number.isFinite(delta)&&Number.isFinite(tolerance)))throw Error('Perturbation and tolerance must be positive finite values.');const data=await toolCompute('divergence',cfg,delta,tolerance);comparison=data.b;$('.legend-b').hidden=false;$('#toolResults').innerHTML=resultCards([['First tolerance crossing',data.horizon===null?'Not reached':fmt(data.horizon,2)+(cfg.system==='logistic'?' n':' s')],['Final absolute divergence',data.values.at(-1).toExponential(3)],['Final relative divergence',data.relative.at(-1).toExponential(3)]]);lineChart($('#toolChart'),[data.values],['#b297ff'],{log:true,xValues:data.a.times});$('#inspectHorizon').hidden=false;$('#inspectHorizon').onclick=()=>{$('#toolDialog').close();activeTab='simulation';setPage('lab');progress=data.horizon===null?1:Math.max(.001,data.horizon/result.times.at(-1));playing=false;$('#play').textContent='▶';$('#plotStatus').textContent='PAUSED · COMPARING TRAJECTORIES';toast('Two trajectories loaded. Scrub the timeline to inspect their separation.');};});$('#computeTool').onclick=run;run();return;}
 if(name==='Lyapunov Analyzer'){openDialog(name,`<p>Largest finite-time Lyapunov estimate for ${systems[cfg.system].name}. A nearby trajectory is periodically rescaled to measure average exponential separation.</p><div class="tool-equation">λ̂(T) = (1 / T) Σ log(δᵢ / δ₀)</div><div class="tool-controls"><label>Estimation interval (s)<input id="lyapDuration" type="number" class="tool-input" value="100" min="20" max="500"></label><button id="computeTool">Estimate exponent</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Finite-time, single-vector estimate, using RK4 and a 10 s transient for continuous systems. Convergence can be slow. Repeat with smaller steps and longer intervals; a positive estimate alone is not a rigorous proof of chaos. Logistic results are per iteration.</p>`);const run=()=>busy($('#computeTool'),async()=>{const duration=Number($('#lyapDuration').value);if(duration<20||duration>500||!Number.isFinite(duration))throw Error('Use an interval from 20 to 500 seconds.');const l=await toolCompute('lyapunov',cfg,duration);$('#toolResults').innerHTML=resultCards([['Estimated λₘₐₓ',fmt(l.value,5)],['Units',l.units],['Interpretation',l.value>.05?'Sensitive':l.value<-.05?'Contracting':'Near zero']]);lineChart($('#toolChart'),[l.history],['#b297ff']);});$('#computeTool').onclick=run;run();return;}
 if(name==='Bifurcation Explorer'){openDialog(name,`<p>Logistic map: discard 1,100 transient iterations and plot the next 200 at each of 900 parameter values. Change the parameter interval to zoom into the cascade. Click the diagram to inspect a value.</p><div class="tool-equation">xₙ₊₁ = r xₙ(1 − xₙ), x₀ = 0.2</div><div class="tool-controls"><label>Lower r<input class="tool-input" id="rMin" type="number" value="2.5" min="0" max="4" step="0.01"></label><label>Upper r<input class="tool-input" id="rMax" type="number" value="4" min="0" max="4" step="0.01"></label><button id="computeTool">Sweep parameters</button><span id="bifInspect" class="teal"></span></div>${toolChart}<p class="limitation">Finite sweeps can miss narrow periodic windows and long transients. The logistic map is a discrete system; this diagram is not inferred from the continuous model currently in the lab.</p>`);const run=()=>busy($('#computeTool'),async()=>{const min=Number($('#rMin').value),max=Number($('#rMax').value);if(!Number.isFinite(min)||!Number.isFinite(max))throw Error('Enter finite bounds.');const pts=await toolCompute('bifurcation',min,max);scatter($('#toolChart'),pts,{xmin:min,xmax:max,ymin:0,ymax:1,color:'#39e8c3',alpha:.25});$('#toolChart').onclick=e=>{const rect=e.target.getBoundingClientRect();const r=min+(e.clientX-rect.left-35)/(rect.width-50)*(max-min);$('#bifInspect').textContent='r ≈ '+fmt(r,6);};});$('#computeTool').onclick=run;run();return;}
 if(name==='Algorithm Arena'){if(cfg.system==='logistic')return toast('The logistic map is a recurrence; choose a continuous system for solver comparisons.');openDialog(name,`<p>Compare each solver against RK4 at one quarter of the selected step size. Errors below are endpoint differences, not exact error bounds. Chaotic trajectories may separate even for accurate methods.</p><div class="tool-controls"><button id="computeTool">Run benchmark</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Wall-clock timings vary by browser, hardware, and worker load. Adaptive RK uses RK4 step doubling with relative scale tolerance 10⁻⁷. Reference is numerical; no solver is universally superior.</p>`);const run=()=>busy($('#computeTool'),async()=>{const rows=await toolCompute('arena',cfg);$('#toolResults').innerHTML='<table><thead><tr><th>Method</th><th>Endpoint difference</th><th>Time (ms)</th><th>f evaluations</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${r.solver.toUpperCase()}</td><td>${r.error===null?'Diverged':r.error.toExponential(3)}</td><td>${fmt(r.elapsed,2)}</td><td>${r.evals?.toLocaleString()||'—'}</td></tr>`).join('')+'</tbody></table>';const good=rows.filter(r=>r.points);lineChart($('#toolChart'),good.map(r=>r.points.map(p=>p[0])),['#e0ad70','#b297ff','#39e8c3','#5e9ef7'],{xValues:good[0]?.times});});$('#computeTool').onclick=run;run();return;}
 if(name==='Uncertainty Lab'){openDialog(name,`<p>Monte Carlo exploration with uniform perturbations of every initial coordinate. A fixed random seed makes this ensemble reproducible. The chart shows the shaded empirical 10–90% band of x(t), with its median in purple.</p><div class="tool-controls"><label>Ensemble size<input class="tool-input" id="ensembleSize" type="number" value="24" min="5" max="60"></label><label>Uniform half-width<input class="tool-input" id="spread" type="number" value="0.001" min="0.0000001" max="1" step="0.001"></label><button id="computeTool">Run ensemble</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Initial-state uncertainty only. Empirical 10–90% quantiles are not calibrated confidence intervals. Small ensembles undersample rare events. Seed: 41291.</p>`);$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const count=Number($('#ensembleSize').value),spread=Number($('#spread').value);if(!Number.isInteger(count)||count<5||count>60||!Number.isFinite(spread)||spread<=0||spread>1)throw Error('Use 5–60 runs and a spread in (0, 1].');const data=await toolCompute('ensemble',cfg,count,spread);const last=data.bands.at(-1);$('#toolResults').innerHTML=resultCards([['Final x · 10% quantile',fmt(last[1])],['Final x · median',fmt(last[2])],['Final x · 90% quantile',fmt(last[3])]]);lineChart($('#toolChart'),[data.bands.map(b=>b[1]),data.bands.map(b=>b[3]),data.bands.map(b=>b[2])],['#39e8c370','#39e8c370','#b297ff'],{xValues:data.runs[0].times,band:true});});return;}
 if(name==='Recurrence Analysis'){openDialog(name,`<p>A recurrence plot marks pairs of sampled states that lie within a Euclidean distance threshold. Up to 300 states are sampled uniformly across this trajectory.</p><div class="tool-controls"><label>Distance threshold<input class="tool-input" id="threshold" type="number" value="2" min="0.000001" step="0.1"></label><button id="computeTool">Build recurrence plot</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">States are not normalized. Threshold and physical units strongly affect recurrence rate; the main diagonal is excluded from the reported rate. No single recurrence metric proves chaos.</p>`);const run=()=>busy($('#computeTool'),async()=>{const th=Number($('#threshold').value);if(!(th>0&&Number.isFinite(th)))throw Error('Enter a positive finite threshold.');const r=await toolCompute('recurrence',result.points,th);$('#toolResults').innerHTML=resultCards([['Recurrence rate',fmt(r.rate*100,2)+'%'],['Sampled states',r.size],['Distance metric','Euclidean']]);scatter($('#toolChart'),r.pixels,{xmin:0,xmax:r.size,ymin:0,ymax:r.size,color:'#b297ff',alpha:.7});});$('#computeTool').onclick=run;run();return;}
 if(name==='Fractal Analysis'){openDialog(name,`<p>Estimate the box-counting slope of the sampled trajectory, normalized along each of its first three coordinates. The fit uses four resolutions: 4, 8, 16, and 32 bins per axis.</p><div id="toolResults">Computing…</div>${toolChart}<p class="limitation">This finite-resolution slope is not a rigorous fractal dimension. Transients, sample density, scale selection, normalization, and projection all bias the result. Correlation dimension estimation is not included in this release.</p>`);try{const r=await toolCompute('boxDimension',result.points.slice(Math.floor(result.points.length*.2)));$('#toolResults').innerHTML=resultCards([['Box-counting slope',fmt(r.value,3)],['Scales fitted','4'],['Transient discarded','20%']]);scatter($('#toolChart'),r.counts,{color:'#39e8c3',radius:4});}catch(e){toast(e.message);}return;}
 if(name==='Poincaré Section'){if(result.points[0].length<3)return toast('Choose a system with at least three state variables.');openDialog(name,`<p>Intersect the trajectory with z = c, retaining upward crossings. Linear interpolation locates the crossing between successive samples.</p><div class="tool-controls"><label>Section level c<input class="tool-input" id="sectionLevel" type="number" value="25" step="0.5"></label><button id="computeTool">Build section</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">This is a coordinate plane section. It is useful only when the trajectory crosses the plane transversely. Sparse sampling and short runs can miss structure.</p>`);const run=()=>{const level=Number($('#sectionLevel').value);const pts=[];for(let i=1;i<result.points.length;i++){const a=result.points[i-1],b=result.points[i];if(a[2]<level&&b[2]>=level){const u=(level-a[2])/(b[2]-a[2]);pts.push([a[0]+u*(b[0]-a[0]),a[1]+u*(b[1]-a[1])]);}}$('#toolResults').innerHTML=resultCards([['Upward crossings',pts.length],['Section','z = '+level],['Coordinates','x, y']]);scatter($('#toolChart'),pts,{color:'#b297ff',radius:3});};$('#computeTool').onclick=run;run();return;}
 if(name==='Sensitivity Analysis'){openDialog(name,`<p>Central finite differences estimate sensitivity of the final state to each model parameter. Changes are measured in raw state units per parameter unit.</p><div class="tool-controls"><button id="computeTool">Compute local sensitivities</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Local endpoint derivatives are strongly horizon-dependent in chaotic systems. Finite perturbations and numerical error can overwhelm a derivative estimate. These are not global sensitivity indices.</p>`);$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const rows=[];for(const [key,, ,min,max]of systems[cfg.system].params){const h=Math.max(1e-5,Math.abs(cfg.params[key])*.001),lo=Math.max(min,cfg.params[key]-h),hi=Math.min(max,cfg.params[key]+h);const a=await toolCompute('simulate',{...cfg,params:{...cfg.params,[key]:lo}}),b=await toolCompute('simulate',{...cfg,params:{...cfg.params,[key]:hi}});rows.push([key,b.points.at(-1).map((v,j)=>(v-a.points.at(-1)[j])/(hi-lo))]);}$('#toolResults').innerHTML='<table><thead><tr><th>Parameter</th>'+cfg.initial.map((_,i)=>'<th>∂x'+i+'(T) / ∂p</th>').join('')+'</tr></thead><tbody>'+rows.map(([key,values])=>'<tr><td>'+key+'</td>'+values.map(v=>'<td style="color:'+(v>=0?'#39e8c3':'#b297ff')+'">'+v.toExponential(3)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';lineChart($('#toolChart'),rows.map(r=>r[1]),['#39e8c3','#b297ff','#5e9ef7']);});return;}
 if(name==='Custom Equation Lab'){openDialog(name,`<p>Define two autonomous differential equations in x and y. Expressions support + − × / ^, parentheses, sin, cos, tan, exp, log, sqrt, abs and pi. The safe parser rejects property access and arbitrary code.</p><div class="tool-controls"><label>dx/dt<input class="tool-input" id="customX" style="width:240px" value="y"></label><label>dy/dt<input class="tool-input" id="customY" style="width:240px" value="-x - 0.2*y"></label></div><div class="tool-controls"><label>Initial x<input class="tool-input" id="customInitialX" type="number" value="2"></label><label>Initial y<input class="tool-input" id="customInitialY" type="number" value="0"></label><button id="computeTool">Validate & simulate</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Bounded 2D experiment: RK4, Δt = 0.01, 30 s. Expressions must remain finite along the solution. This is an experimental equation sandbox.</p>`);$('#computeTool').onclick=()=>{try{const fx=parseExpression($('#customX').value,['x','y','t']),fy=parseExpression($('#customY').value,['x','y','t']);const f=([x,y],p,t)=>[fx({x,y,t}),fy({x,y,t})];let state=[Number($('#customInitialX').value),Number($('#customInitialY').value)];const pts=[state];for(let i=0;i<3000;i++){state=step(f,state,{},i*.01,.01);if(state.some(v=>!Number.isFinite(v)||Math.abs(v)>1e8))throw Error('Solution became non-finite or unbounded.');pts.push(state);}$('#toolResults').innerHTML=resultCards([['Final x',fmt(state[0],4)],['Final y',fmt(state[1],4)],['Integration','RK4']]);scatter($('#toolChart'),pts,{color:'#39e8c3',radius:.7,connect:true});}catch(e){toast(e.message);}};return;}
 if(name==='Inverse Chaos Solver'){openInverse();return;}if(name==='Chaos Control'){openControl();return;}if(name==='Chaos vs Randomness'){openRandomness();return;}if(name==='Coupled Chaos Network'){openNetwork();return;}if(name==='Parameter Estimation'||name==='System Identification'){openDataTool(name);return;}
}
function scatter(canvas,pts,{xmin,xmax,ymin,ymax,color='#39e8c3',alpha=.8,radius=1,connect=false}={}){const sized=sizeCanvas(canvas);if(!sized)return;const{ctx,w,h}=sized;ctx.clearRect(0,0,w,h);if(!pts.length){ctx.fillStyle='#839bab';ctx.font='12px sans-serif';ctx.fillText('No crossings or finite points in this interval.',30,h/2);return;}const bounds=pts.reduce((b,p)=>[Math.min(b[0],p[0]),Math.max(b[1],p[0]),Math.min(b[2],p[1]),Math.max(b[3],p[1])],[Infinity,-Infinity,Infinity,-Infinity]);xmin??=bounds[0];xmax??=bounds[1];ymin??=bounds[2];ymax??=bounds[3];ctx.font='9px monospace';ctx.fillStyle='#698595';ctx.textAlign='center';for(let i=0;i<=4;i++){const x=35+(w-50)*i/4,y=15+(h-45)*i/4;ctx.fillText(fmt(xmin+(xmax-xmin)*i/4,2),x,h-10);ctx.textAlign='right';ctx.fillText(fmt(ymax-(ymax-ymin)*i/4,2),30,y+3);ctx.textAlign='center';ctx.strokeStyle='#1b2d37';ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(w-15,y);ctx.stroke();}ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=.8;ctx.globalAlpha=alpha;if(connect)ctx.beginPath();pts.forEach((p,i)=>{const x=35+(p[0]-xmin)/(xmax-xmin||1)*(w-50),y=h-30-(p[1]-ymin)/(ymax-ymin||1)*(h-45);if(connect){i?ctx.lineTo(x,y):ctx.moveTo(x,y);}else{ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.fill();}});if(connect)ctx.stroke();ctx.globalAlpha=1;}
$$('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));$('#challenge').onclick=()=>openTool('Chaos Challenge');$('#configInfo').onclick=()=>{openDialog(systems[cfg.system].name,`<p>${systems[cfg.system].description}</p><div class="tool-equation">${systems[cfg.system].equations.join('<br>')}</div><p>State dimension: ${cfg.initial.length}. Parameters and initial conditions are editable in the configuration panel. All integration is performed with JavaScript Float64 numbers in a dedicated worker.</p><p class="limitation">These models are idealizations. Numerical trajectories and diagnostic estimates depend on solver settings and are not exact mathematical solutions.</p>`);};
$('#help').onclick=()=>openDialog('Methods & reproducibility',`<p>TOSIN is a browser-native toolkit for oscillatory systems, instability and nonlinearity. No data is sent to an AI model. Numerical work runs locally.</p><div class="tool-equation">Define → Simulate → Visualize → Analyze → Reproduce → Export</div><p><strong>Solvers.</strong> Forward Euler (order 1), Heun (order 2), classical RK4 (order 4), and adaptive RK4 step doubling. Adaptive tolerance is 10⁻⁷ × (1 + ‖state‖). Integrations retain up to roughly 12,000 output points; internal steps may be smaller.</p><p><strong>Inspect.</strong> Drag the phase portrait to rotate. Shift-drag to pan. Scroll to zoom. Pause and hover near a trajectory to inspect state values. Scrub the timeline to compare nearby futures.</p><p><strong>Reproduce.</strong> Save an experiment locally, export its JSON configuration, and export its CSV trajectory. Uncertainty ensembles use a fixed random seed. Browser storage is device-specific.</p><p class="limitation">This is an experimental scientific computing release. Verify conclusions using step refinement, independent software and model-specific mathematical analysis. Estimates are not proofs. Timing results are browser-dependent.</p>`);
$('#shortcuts').onclick=()=>openDialog('Keyboard & interaction guide','<div class="tool-equation">Space — Pause / resume<br>Esc — Close workbench or expanded plot<br>Drag — Rotate phase space<br>Shift + drag — Pan<br>Scroll — Zoom<br>Pause + hover — Inspect state values</div>');document.addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(document.activeElement.tagName)&&!$('#toolDialog').open){e.preventDefault();$('#play').click();}if(e.key==='Escape')$('.phase-panel').classList.remove('fullscreen');});
window.addEventListener('resize',()=>{updateTimeChart();});
renderConfig();runSimulation();
function openInverse(){if(cfg.system==='logistic')return toast('Choose a continuous system for this optimization experiment.');openDialog('Inverse Chaos Solver',`<p>Search initial coordinates using derivative-free coordinate descent to bring the endpoint near a target. The optimizer starts from your current initial state. This is a numerical search, not an exact inverse.</p><div class="tool-equation">minimize J(x₀) = ‖Φᵀ(x₀) − x_target‖₂</div><div class="tool-controls">${cfg.initial.map((v,i)=>`<label>Target coordinate ${i+1}<input class="tool-input" data-target="${i}" type="number" step="any" value="${i===2?25:0}"></label>`).join('')}<label>Horizon (s)<input class="tool-input" id="inverseTime" type="number" value="2" min="0.5" max="10" step="0.5"></label><button id="computeTool">Search candidates</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">60 coordinate-descent iterations with shrinking search steps. Local optima, unreachable targets and severe sensitivity are possible. There is no global optimality guarantee. Residual is in raw state units.</p>`);$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const target=$$('[data-target]').map(el=>Number(el.value)),horizon=Number($('#inverseTime').value);if(horizon<.5||horizon>10||!Number.isFinite(horizon))throw Error('Use a horizon of 0.5–10 seconds.');const data=await toolCompute('inverseSearch',cfg,target,horizon);$('#toolResults').innerHTML=resultCards([['Best residual',data.residual.toExponential(3)],['Objective evaluations',data.evaluations],['Iterations',data.history.length]])+'<div class="tool-equation">Candidate x₀ = ['+data.candidate.map(v=>fmt(v,5)).join(', ')+']</div>';lineChart($('#toolChart'),[data.history],['#39e8c3']);});}
function openControl(){if(cfg.system==='logistic')return toast('Choose a continuous system for feedback control.');openDialog('Chaos Control',`<p>Apply proportional feedback to the first state derivative while preserving the rest of the model. Compare the controlled and unmodified first coordinates.</p><div class="tool-equation">ẋ₁ = f₁(x,t) + u &nbsp; · &nbsp; u = −K(x₁ − x*)</div><div class="tool-controls"><label>Feedback gain K<input class="tool-input" id="controlGain" type="number" value="2" min="0" max="30" step="0.5"></label><label>Target x*<input class="tool-input" id="controlTarget" type="number" value="0" step="any"></label><button id="computeTool">Apply feedback</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Assumes direct actuation of the first state derivative and complete state measurement. This educational feedback experiment is not an OGY controller or a proof of stabilization. Physical control constraints are not modeled.</p>`);$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const gain=Number($('#controlGain').value),target=Number($('#controlTarget').value);if(!Number.isFinite(gain)||!Number.isFinite(target)||gain<0||gain>30)throw Error('Use a finite target and a gain in [0,30].');const r=await toolCompute('controlled',cfg,gain,target);$('#toolResults').innerHTML=resultCards([['Final |x − target|',fmt(r.finalError,5)],['Maximum |control|',fmt(Math.max(...r.effort.map(Math.abs)),3)],['Feedback gain',fmt(gain,2)]]);const original=await toolCompute('simulate',{...cfg,dt:r.times[1],duration:r.times.at(-1)});const limit=Math.min(r.points.length,original.points.length);lineChart($('#toolChart'),[r.points.slice(0,limit).map(p=>p[0]),original.points.slice(0,limit).map(p=>p[0])],['#39e8c3','#b297ff'],{xValues:r.times});});}
function openRandomness(){openDialog('Chaos vs Randomness',`<p>Add independent uniform measurement noise to x(t). Compare roughness and turning points with the deterministic model’s Lyapunov estimate. Classification is explicitly heuristic.</p><div class="tool-controls"><label>Noise half-width<input class="tool-input" id="noiseWidth" type="number" value="0.5" min="0" max="100" step="0.1"></label><button id="computeTool">Analyze signal</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">Noise is observational, not a stochastic differential equation. Periodic versus quasi-periodic behavior is not resolved here. No metric alone proves chaos or randomness. Finite data and sampling may produce an inconclusive result. Seed: 95377.</p>`);$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const width=Number($('#noiseWidth').value);if(!Number.isFinite(width)||width<0||width>100)throw Error('Noise half-width must lie in [0,100].');const r=await toolCompute('noisySeries',cfg,width);$('#toolResults').innerHTML='<div class="tool-equation">Heuristic result: '+r.interpretation+'</div>'+resultCards([['Normalized roughness',fmt(r.roughness,5)],['Turning-point fraction',fmt(r.turningRate,4)],['Model Lyapunov estimate',fmt(r.lyapunov,4)]]);lineChart($('#toolChart'),[r.values,r.clean],['#b297ff80','#39e8c3'],{xValues:r.times});});}
function openNetwork(){openDialog('Coupled Chaos Network',`<p>Explore synchronization in a network of Kuramoto phase oscillators. Natural frequencies are fixed and heterogeneous. Change topology and coupling to observe collective behavior.</p><div class="tool-equation">θ̇ᵢ = ωᵢ + (K / degreeᵢ) Σⱼ sin(θⱼ − θᵢ)</div><div class="tool-controls"><label>Oscillators<input class="tool-input" id="networkSize" type="number" value="12" min="3" max="30"></label><label>Coupling K<input class="tool-input" id="networkCoupling" type="number" value="0.8" min="0" max="3" step="0.1"></label><label>Topology<select id="networkTopology"><option value="ring">Ring</option><option value="all">All-to-all</option><option value="star">Star</option></select></label><button id="computeTool">Simulate network</button></div><div id="toolResults"></div><canvas id="networkChart" class="tool-chart" style="height:240px"></canvas>${toolChart}<p class="limitation">This is a phase synchronization model, not a network of chaotic Lorenz systems. Order parameter R ∈ [0,1] measures phase coherence; full coherence does not establish frequency locking or chaos. Euler integration at Δt = 0.02, 50 s. Cascading failure dynamics are outside this model.</p>`);const run=()=>busy($('#computeTool'),async()=>{const r=await toolCompute('networkSimulation',Number($('#networkSize').value),Number($('#networkCoupling').value),$('#networkTopology').value);$('#toolResults').innerHTML=resultCards([['Final coherence R',fmt(r.order.at(-1),4)],['Network edges',r.edges.length],['Model','Kuramoto']]);lineChart($('#toolChart'),[r.order],['#39e8c3']);const sized=sizeCanvas($('#networkChart'));if(!sized)return;const{ctx,w,h}=sized;ctx.clearRect(0,0,w,h);const phases=r.points.at(-1),n=phases.length,rad=Math.min(w*.3,h*.38),nodes=phases.map((p,i)=>[w/2+rad*Math.cos(i*2*Math.PI/n),h/2+rad*Math.sin(i*2*Math.PI/n)]);ctx.strokeStyle='#2f4555';ctx.lineWidth=.7;for(const [i,j]of r.edges){ctx.beginPath();ctx.moveTo(...nodes[i]);ctx.lineTo(...nodes[j]);ctx.stroke();}nodes.forEach(([x,y],i)=>{ctx.fillStyle=`hsl(${150+Math.sin(phases[i])*55} 85% 65%)`;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#8ca5b5';ctx.font='8px monospace';ctx.fillText(i+1,x+9,y+3);});});$('#computeTool').onclick=run;run();}
function openDataTool(name){const fitting=name==='Parameter Estimation';openDialog(name,`<p>${fitting?'Fit the logistic growth parameter r to observed map values by one-step least squares.':'Fit constant, linear, and quadratic discrete recurrence candidates, using a chronological 70% training / 30% validation split.'} Import CSV with either one value per row or an index/time column followed by the observed x value. A single header row is allowed.</p><div class="tool-controls"><label>Time-series CSV<input id="seriesFile" type="file" accept=".csv,text/csv"></label><button id="exampleData">Load example data</button></div><textarea class="tool-textarea" id="seriesData" aria-label="Observed time-series data" placeholder="n,x\n0,0.2\n1,0.624\n2,0.9150336"></textarea><div class="tool-controls"><button id="computeTool">${fitting?'Estimate parameter':'Compare candidate models'}</button></div><div id="toolResults"></div>${toolChart}<p class="limitation">${fitting?'Fits xₙ₊₁ = r xₙ(1 − xₙ), r ∈ [0,4]. The 95% interval uses a linear residual approximation assuming independent, homoscedastic next-step errors and exact predictors; noisy predictors and dependent observations violate this assumption.':'Candidate equations describe a sampled recurrence and are not proven physical laws. One-step validation may hide poor long-term behavior. The library is limited to degree-two polynomials; no causal or physical identification is implied.'}</p>`);$('#seriesFile').onchange=async e=>{const file=e.target.files[0];if(file?.size>2e6)return toast('Use a CSV smaller than 2 MB.');if(file)$('#seriesData').value=await file.text();};$('#exampleData').onclick=()=>{let x=.2;const rows=['n,x'];for(let i=0;i<200;i++){rows.push(i+','+x);x=3.9*x*(1-x);}$('#seriesData').value=rows.join('\n');};$('#computeTool').onclick=()=>busy($('#computeTool'),async()=>{const rows=$('#seriesData').value.trim().split(/\r?\n/).filter(Boolean);if(rows.length>20000)throw Error('Limit the data to 20,000 rows.');const data=[];rows.forEach((row,i)=>{const cols=row.split(/[,;\t]/).map(x=>x.trim()),raw=cols.length>1?cols[1]:cols[0],v=Number(raw);if(raw===''||!Number.isFinite(v)){if(i===0)return;throw Error('Non-numeric observation at row '+(i+1));}data.push(v);});if(data.some(v=>Math.abs(v)>1e8))throw Error('Scale observations to finite values below 10⁸.');if(fitting){const r=await toolCompute('fitLogistic',data);$('#toolResults').innerHTML=resultCards([['Fitted r',fmt(r.r,6)],['One-step RMSE',r.rmse.toExponential(3)],['R²',fmt(r.r2,5)]])+'<div class="tool-equation">Approximate 95% interval: ['+fmt(r.lower,6)+', '+fmt(r.upper,6)+']</div><p>Teal: observed next state · Purple: one-step fitted prediction</p>';lineChart($('#toolChart'),[data.slice(1),r.predicted],['#39e8c3','#b297ff']);}else{const candidates=await toolCompute('identify',data);$('#toolResults').innerHTML='<table><thead><tr><th>Candidate</th><th>Train RMSE</th><th>Validation RMSE</th></tr></thead><tbody>'+candidates.map(r=>`<tr><td>${r.name}</td><td>${r.train.toExponential(3)}</td><td>${r.validation.toExponential(3)}</td></tr>`).join('')+'</tbody></table><div class="tool-equation">Lowest held-out error: '+candidates[0].equation+'</div>';lineChart($('#toolChart'),[data],['#39e8c3']);}});}
